import React, { Component } from "react";

class FeelingProud extends Component {
  render() {
    return (
      <img
        src="adlynwebsite.png"   // ✅ path from public folder
        alt="Feeling Proud Graphic"
        style={{
          width: "150%",
          height: "auto",
          maxWidth: "1200px",
          display: "block",
          margin: "0 auto",
          position: "relative",
          right: "140px"
        }}
      />
    );
  }
}

export default FeelingProud;
